def integer_break(n):
    def helper(remaining):
        if remaining == 1:
            return 1
        best = 0
        for j in range(1, remaining):
            rest = max(remaining - j, helper(remaining - j))    # leave whole, or split further
            best = max(best, j * rest)                              # no caching, recomputes shared work
        return best
    return helper(n)

