def integer_break(n):
    if n == 2:
        return 1
    if n == 3:
        return 2
    product = 1
    while n > 4:
        product *= 3                # 3 is the optimal piece size to repeatedly break off
        n -= 3
    return product * n              # multiply in whatever remains (2, 3, or 4)

